 const { chromium } = require('playwright-chromium');
 const fs = require('fs');
 const path = require('path');

 async function runTest() {
     const browser = await chromium.launch();
     const page = await browser.newPage();

     // Read the files to set up the environment
     const htmlContent = fs.readFileSync('index.html', 'utf8');
     const cssContent = fs.readFileSync('css/styles.css', 'utf8');
     const jsContent = fs.readFileSync('js/app.js', 'utf8');

     // We'll set the content and inject scripts manually because they are external CDN scripts
     // Use a real server or data URL to handle relative paths and script execution
     const absoluteHtmlPath = path.resolve('index.html');
     await page.goto(`file://${absoluteHtmlPath}`);

     // Check if .trigger exists and wait for it
     try {
         await page.waitForSelector('.trigger', { timeout: 15000 });
     } catch (e) {
         console.log('Current page content:', await page.content());
         throw e;
     }

     // Inject axe-core
     await page.addScriptTag({ path: '/tmp/axe.min.js' });

     // Test the initial state (modal closed)
     console.log('--- Initial State ---');
     const results1 = await page.evaluate(async () => await window.axe.run());
     printViolations(results1);

     // Test with modal open
     console.log('\n--- Modal Open ---');
     await page.click('.trigger');
     await page.waitForSelector('dialog[open]');
     const results2 = await page.evaluate(async () => await window.axe.run());
     printViolations(results2);

     await browser.close();
 }

 function printViolations(results) {
     const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
     const bp = results.violations.filter(v => v.tags.includes('best-practice'));

     console.log(JSON.stringify({
         wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
         bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
     }, null, 2));
 }

 runTest().catch(err => {
     console.error(err);
     process.exit(1);
 });

