 const { useState, useRef, useEffect } = React;

 const Modal = ({ isOpen, onClose, onConfirm, title, children }) => {
     const dialogRef = useRef(null);

     useEffect(() => {
         const dialog = dialogRef.current;
         if (isOpen) {
             if (!dialog.open) {
                 dialog.showModal();
             }
         } else {
             if (dialog.open) {
                 dialog.close();
             }
         }
     }, [isOpen]);

     useEffect(() => {
         const dialog = dialogRef.current;
         const handleCancel = (e) => {
             e.preventDefault();
             onClose();
         };
         dialog.addEventListener('cancel', handleCancel);
         return () => dialog.removeEventListener('cancel', handleCancel);
     }, [onClose]);

     return (
         <dialog 
             ref={dialogRef}
             aria-labelledby="modal-title"
             aria-modal="true"
         >
             <div className="modal-content">
                 <h2 id="modal-title">{title}</h2>
                 {children}
                 <div className="modal-actions">
                     <button 
                         type="button" 
                         className="btn btn-secondary" 
                         onClick={onClose}
                     >
                         Cancel
                     </button>
                     <button 
                         type="button" 
                         className="btn btn-danger" 
                         onClick={onConfirm}
                     >
                         Delete
                     </button>
                 </div>
             </div>
         </dialog>
     );
 };

 const App = () => {
     const [isModalOpen, setIsModalOpen] = useState(false);
     const [isDeleted, setIsDeleted] = useState(false);

     const handleDeleteClick = () => {
         setIsModalOpen(true);
     };

     const handleCloseModal = () => {
         setIsModalOpen(false);
     };

     const handleConfirmDelete = () => {
         setIsDeleted(true);
         setIsModalOpen(false);
     };

     // Ensure focus returns to the trigger when modal closes
     // Native <dialog> does this automatically if showModal() was used.

     return (
         <main className="image-preview-container">
             <h1>Image Library</h1>
             <div className="image-preview" role="img" aria-label="Image preview">
                 {isDeleted ? (
                     <p>Image deleted</p>
                 ) : (
                     <div style={{width: '100%', height: '100%', backgroundColor: '#2a2a2a', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center'}}>
                          {/* Placeholder for an image */}
                          <svg width="48" height="48" viewBox="0 0 24 24" fill="var(--text-secondary)" aria-hidden="true">
                             <path d="M21 19V5c0-1.1-.9-2-2-2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2zM8.5 13.5l2.5 3.01L14.5 12l4.5 6H5l3.5-4.5z"/>
                          </svg>
                          <span style={{marginTop: '10px'}}>Landscape_01.jpg</span>
                     </div>
                 )}
             </div>

             {!isDeleted && (
                 <button 
                     type="button" 
                     className="trigger"
                     onClick={handleDeleteClick}
                 >
                     Delete Image
                 </button>
             )}

             {isDeleted && (
                 <button 
                     type="button" 
                     className="btn btn-secondary"
                     onClick={() => setIsDeleted(false)}
                 >
                     Restore (for demo)
                 </button>
             )}

             <Modal 
                 isOpen={isModalOpen} 
                 onClose={handleCloseModal}
                 onConfirm={handleConfirmDelete}
                 title="Confirm Deletion"
             >
                 <p>Are you sure you want to delete this image? This action cannot be undone.</p>
             </Modal>
         </main>
     );
 };

 const root = ReactDOM.createRoot(document.getElementById('root'));
 root.render(<App />);

