    await page.click('.trigger');
    await page.waitForSelector('dialog[open]');
    const results2 = await page.evaluate(async () => await window.axe.run());
    printViolations(results2);

    // Test after deletion
    console.log('\n--- After Deletion ---');
    await page.click('button.btn-danger'); // Click Delete in modal
    await page.waitForSelector('text=Image deleted');
    const results3 = await page.evaluate(async () => await window.axe.run());
    printViolations(results3);

    await browser.close();
}

