     <script>
         const { useState, useRef, useEffect, createElement: h } = React;

         const Modal = ({ isOpen, onClose, onConfirm, title, children }) => {
             const dialogRef = useRef(null);

             useEffect(() => {
                 const dialog = dialogRef.current;
                 if (isOpen) {
                     if (!dialog.open) {
                         dialog.showModal();
                     }
                 } else {
                     if (dialog.open) {
                         dialog.close();
                     }
                 }
             }, [isOpen]);

             useEffect(() => {
                 const dialog = dialogRef.current;
                 const handleCancel = (e) => {
                     e.preventDefault();
                     onClose();
                 };
                 dialog.addEventListener('cancel', handleCancel);
                 return () => dialog.removeEventListener('cancel', handleCancel);
             }, [onClose]);

             return h('dialog', {
                 ref: dialogRef,
                 'aria-labelledby': 'modal-title',
                 'aria-modal': 'true'
             }, 
                 h('div', { className: 'modal-content' },
                     h('h2', { id: 'modal-title' }, title),
                     children,
                     h('div', { className: 'modal-actions' },
                         h('button', {
                             type: 'button',
                             className: 'btn btn-secondary',
                             onClick: onClose
                         }, 'Cancel'),
                         h('button', {
                             type: 'button',
                             className: 'btn btn-danger',
                             onClick: onConfirm
                         }, 'Delete')
                     )
                 )
             );
         };

         const App = () => {
             const [isModalOpen, setIsModalOpen] = useState(false);
             const [isDeleted, setIsDeleted] = useState(false);
             const restoreBtnRef = useRef(null);
             const triggerBtnRef = useRef(null);

             const handleDeleteClick = () => {
                 setIsModalOpen(true);
             };

             const handleCloseModal = () => {
                 setIsModalOpen(false);
             };

             const handleConfirmDelete = () => {
                 setIsDeleted(true);
                 setIsModalOpen(false);
             };

             const handleRestore = () => {
                 setIsDeleted(false);
             };

             // Focus management after state changes
             useEffect(() => {
                 if (isDeleted && restoreBtnRef.current) {
                     restoreBtnRef.current.focus();
                 } else if (!isDeleted && triggerBtnRef.current) {
                     triggerBtnRef.current.focus();
                 }
             }, [isDeleted]);

             return h('main', { className: 'image-preview-container' },
                 h('h1', null, 'Image Library'),
                 h('div', { 
                     className: 'image-preview', 
                     role: 'img', 
                     'aria-label': isDeleted ? 'Image preview: No image' : 'Image preview: Landscape_01.jpg',
                     'aria-live': 'polite'
                 }, 
                     isDeleted ? h('p', null, 'Image deleted') : [
                         h('svg', { 
                             key: 'svg',
                             width: '48', 
                             height: '48', 
                             viewBox: '0 0 24 24', 
                             fill: 'var(--text-secondary)', 
                             'aria-hidden': 'true' 
                         }, 
                             h('path', { d: 'M21 19V5c0-1.1-.9-2-2-2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2zM8.5 13.5l2.5 3.01L14.5 12l4.5 6H5l3.5-4.5z' })
                         ),
                         h('span', { key: 'name', style: { marginTop: '10px' } }, 'Landscape_01.jpg')
                     ]
                 ),

                 !isDeleted && h('button', {
                     ref: triggerBtnRef,
                     type: 'button',
                     className: 'trigger',
                     onClick: handleDeleteClick
                 }, 'Delete Image'),

                 isDeleted && h('button', {
                     ref: restoreBtnRef,
                     type: 'button',
                     className: 'btn btn-secondary',
                     onClick: handleRestore
                 }, 'Restore (for demo)'),

                 h(Modal, {
                     isOpen: isModalOpen,
                     onClose: handleCloseModal,
                     onConfirm: handleConfirmDelete,
                     title: 'Confirm Deletion'
                 }, h('p', null, 'Are you sure you want to delete this image? This action cannot be undone.'))
             );
         };

         const root = ReactDOM.createRoot(document.getElementById('root'));
         root.render(h(App));
     </script>
